data: {"type":"response.completed","response":{"id":"resp_02b8278095951c90016adf85e62a7887d297e0ee773bccbf3c","object":"response","created_at":1793033702,"status":"completed","access_programs":{"cyber":"daybreak_blue"},"background":false,"completed_at":1793033709,"error":null,"frequency_penalty":0.0,"incomplete_details":null,"instructions":null,"max_output_tokens":null,"max_tool_calls":null,"model":"gpt-6-luna","moderation":null,"output":[],"parallel_tool_calls":true,"presence_penalty":0.0,"previous_response_id":null,"prompt_cache_key":"01a17922-eee7-7755-b079-a14b0975e987","prompt_cache_retention":"24h","reasoning":{"context":"all_turns","effort":"none","mode":"standard","summary":null},"safety_identifier":"user-0InQm55Bkaiqn2DXMgV7T4o4","service_tier":"default","store":false,"temperature":1.0,"text":{"format":{"type":"text"},"verbosity":"medium"},"tool_choice":"none","tool_usage":{"image_gen":{"input_tokens":0,"input_tokens_details":{"image_tokens":0,"text_tokens":0},"output_tokens":0,"output_tokens_details":{"image_tokens":0,"text_tokens":0},"total_tokens":0},"web_search":{"num_requests":0}},"tools":[{"type":"function","description":"Long-session context management via the pi session tree. Anchor named milestones, then collapse work between them into a model-generated summary to free context.\n`rewind` does not restore prior state: it forks a sibling branch from the anchor and continues forward from a model-generated summary.\n\nOperations (set `action`):\n  • 'anchor', name='<milestone-name>': label the current point. Anchor at the start of a stage you'll summarize (e.g. 'impl-start').\n  • 'rewind', rewindTo='<existing>', newLabel='<new>': collapse work between rewindTo and the current leaf into a branch_summary labeled newLabel, so rewinds can chain.\n  • 'list': show all anchors on the active branch, oldest first, with cumulative context % at each.\n  • 'pin', kind='sub-goal'|'decision'|'fact'|'file'|'steering', text='<what to keep>': record a durable item that survives folds; `list` shows them. 'file' takes path+why instead of text; 'steering' belongs to an anchor (scopeAnchor, default newest). Refused when the user disabled the continuity ledger (continuity.capture=false).\n\n`name` (anchor) and `newLabel` (rewind) write into one shared anchor namespace: labels are unique on the active branch — both actions refuse a name that already exists — and everything written there is addressable as a future `rewindTo`. Avoid the reserved `anchor:` prefix.","name":"navigate_tree","output_schema":null,"parameters":{"type":"object","required":["action"],"properties":{"action":{"anyOf":[{"type":"string","const":"anchor"},{"type":"string","const":"rewind"},{"type":"string","const":"list"},{"type":"string","const":"pin"}],"description":"Which operation to perform."},"name":{"type":"string","description":"Required when action='anchor'. Kebab-case milestone label, max 40 chars."},"rewindTo":{"type":"string","description":"Required when action='rewind'. Kebab-case name of an existing anchor on the active branch to rewind to."},"newLabel":{"type":"string","description":"Required when action='rewind'. Kebab-case label for the resulting branch_summary entry; reusable as a future rewindTo."},"summaryFocus":{"type":"string","description":"Required when action='rewind'; ≥20 chars after trim. Encode: (1) the user's most recent instruction verbatim, (2) what's done in the collapsed segment, (3) what's left to do as a next action; if the user authorized continuing, name the next work item, not a report or wrap-up."},"kind":{"anyOf":[{"type":"string","const":"sub-goal"},{"type":"string","const":"decision"},{"type":"string","const":"fact"},{"type":"string","const":"file"},{"type":"string","const":"steering"}],"description":"Required when action='pin'. Your sub-goal, a decision you made, a key fact, a file pointer, or steering that lapses when its anchor is folded."},"text":{"type":"string","description":"Required when action='pin' unless kind='file'. What to remember, max 500 chars."},"path":{"type":"string","description":"Required when action='pin' and kind='file'. File path."},"lines":{"type":"string","description":"Optional with kind='file': N or N-M."},"why":{"type":"string","description":"Required when action='pin' and kind='file'. Why the file matters."},"scopeAnchor":{"type":"string","description":"Anchor name for kind='steering' (default: newest anchor); optional for 'sub-goal'."}}},"strict":false}],"top_logprobs":0,"top_p":0.98,"truncation":"disabled","usage":{"attribution":{"items":{"msg_02b8278095951c90016adf85e6349087d28037cdfee77d8726":{"cache_write_tokens":0,"cached_tokens":95,"content":[{"cache_write_tokens":0,"cached_tokens":95,"input_tokens":95,"output_tokens":0}],"input_tokens":95,"output_tokens":0},"msg_02b8278095951c90016adf85e636dc87d2989eba7b2872820c":{"cache_write_tokens":0,"cached_tokens":57,"content":[{"cache_write_tokens":0,"cached_tokens":57,"input_tokens":57,"output_tokens":0}],"input_tokens":57,"output_tokens":0},"msg_pi_1":{"cache_write_tokens":0,"cached_tokens":12,"content":[{"cache_write_tokens":0,"cached_tokens":12,"input_tokens":12,"output_tokens":0}],"input_tokens":12,"output_tokens":0},"msg_02b8278095951c90016adf85e636f887d299d47050eccbe7e5":{"cache_write_tokens":0,"cached_tokens":4793,"content":[{"cache_write_tokens":0,"cached_tokens":4793,"input_tokens":4793,"output_tokens":0}],"input_tokens":4793,"output_tokens":0},"msg_pi_3":{"cache_write_tokens":0,"cached_tokens":25,"content":[{"cache_write_tokens":0,"cached_tokens":25,"input_tokens":25,"output_tokens":0}],"input_tokens":25,"output_tokens":0},"msg_02b8278095951c90016adf85e6370887d2ae369bc9d82338f5":{"cache_write_tokens":0,"cached_tokens":4793,"content":[{"cache_write_tokens":0,"cached_tokens":4793,"input_tokens":4793,"output_tokens":0}],"input_tokens":4793,"output_tokens":0},"msg_pi_5":{"cache_write_tokens":0,"cached_tokens":25,"content":[{"cache_write_tokens":0,"cached_tokens":25,"input_tokens":25,"output_tokens":0}]